def parse_duration(text):
    text = text.strip()
    if not text:
        raise ValueError("empty string")

    total = 0
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    used = set()

    i = 0
    n = len(text)
    while i < n:
        # skip spaces
        if text[i] == ' ':
            i += 1
            continue

        # parse number
        num_start = i
        while i < n and text[i].isdigit():
            i += 1
        if i == num_start:
            raise ValueError("missing number")
        number = int(text[num_start:i])
        if number <= 0:
            raise ValueError("non-positive number")

        # skip spaces before unit
        while i < n and text[i] == ' ':
            i += 1
        if i >= n:
            raise ValueError("missing unit")

        # parse unit
        unit_start = i
        while i < n and text[i].isalpha():
            i += 1
        if i == unit_start:
            raise ValueError("missing unit")
        unit = text[unit_start:i]
        if unit not in units:
            raise ValueError("unknown unit")
        if unit in used:
            raise ValueError("repeated unit")
        used.add(unit)

        total += number * units[unit]

    return total
